#!/usr/bin/env python3
"""Gera as sete páginas estáticas do Reametaverso.
Requer Python 3 e Node.js, usados somente nesta etapa de geração.
Execute: python3 gerar_site.py
Não faz rede, publicação ou git push. Imagens: importar do pacote completo.
"""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent
(ROOT/'assets').mkdir(exist_ok=True)
(ROOT/'escolas').mkdir(exist_ok=True)
# Executa apenas o arquivo data.js local do próprio projeto.
import subprocess
raw=subprocess.check_output(['node','-e',"global.window={};require(process.argv[1]);console.log(JSON.stringify(window.ReaData))",str(ROOT/'assets/data.js')],text=True)
data=json.loads(raw)
(ROOT/'assets/content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
paths={
'compass':'<circle cx="12" cy="12" r="9"/><path d="M12 1v22M1 12h22M12 5l2 5 5 2-5 2-2 5-2-5-5-2 5-2z"/>',
'book':'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1v14M6 9h3M6 12h3M15 9h3M15 12h3"/>',
'feather':'<path d="M4 21 16 9M6 18c-3-7 6-15 14-15 0 8-6 16-14 15ZM11 7l1 6M15 4l1 5M11 13l6 1"/>',
'orbit':'<circle cx="12" cy="12" r="2"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(-35 12 12)"/><ellipse cx="12" cy="12" rx="4" ry="10" transform="rotate(-35 12 12)"/><circle cx="18" cy="6" r="1"/>',
'leaf':'<path d="M12 21V10M12 16C5 16 3 11 3 5c6 0 9 4 9 11ZM12 13c0-7 4-10 9-10 0 6-3 10-9 10ZM7 10l5 6M17 7l-5 6"/>',
'hands':'<path d="M3 12v6l5 4h8l5-4v-6M3 12c1-2 3-2 3 1v3l3 2M21 12c-1-2-3-2-3 1v3l-3 2M12 12l-5-5C3 3 9 0 12 4c3-4 9-1 5 3z"/>',
'shield':'<path d="m12 2 8 3v6c0 5-4 9-8 11-4-2-8-6-8-11V5zM8 12l3 3 5-6"/>',
'arrow':'<path d="M4 12h16M14 6l6 6-6 6"/>',
'arrow-left':'<path d="M20 12H4M10 6l-6 6 6 6"/>',
'close':'<path d="m6 6 12 12M18 6 6 18"/>',
'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
'focus':'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/><circle cx="12" cy="12" r="3"/>',
'spark':'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4M18 4h4"/>',
'moon':'<path d="M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11Z"/>',
'expand':'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5M3 3l6 6M21 3l-6 6M3 21l6-6M21 21l-6-6"/>',
'check':'<path d="m5 12 4 4L19 6"/>',
'download':'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
'heart':'<path d="M12 20 3 11C-2 3 8-1 12 6c4-7 14-3 9 5Z"/>',
'lock':'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',
'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'
}
def icon(key,cls='icon'): return f'<svg class="{cls}" viewBox="0 0 24 24" aria-hidden="true"><use href="#i-{key}"/></svg>'
sprite='<svg class="sprite" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs>'+''.join(f'<symbol id="i-{k}" viewBox="0 0 24 24">{v}</symbol>' for k,v in paths.items())+'</defs></svg>'
def brand(prefix=''):
 return f'<a class="brand" href="{prefix}index.html" aria-label="Reametaverso — início">{icon("compass","icon brand-mark")}<span class="brand-name">REAMETAVERSO<span class="brand-sub">MAGIA · HUMANIDADE · NATUREZA</span></span></a>'
def header(prefix=''):
 return f'''<a class="skip-link" href="#conteudo">Ir para o conteúdo</a>{sprite}
<header class="header"><div class="container header-inner">{brand(prefix)}
<nav class="nav" id="navigation" aria-label="Navegação principal"><a href="{prefix}index.html#universo">O universo</a><a href="{prefix}index.html#escolas">As escolas</a><a href="{prefix}index.html#atlas">O atlas</a><a href="{prefix}index.html#manifesto">O manifesto</a></nav>
<div class="header-actions"><button class="icon-button" type="button" data-focus aria-pressed="false" aria-label="Ativar modo foco" title="Modo foco: menos estímulos">{icon('focus')}</button><button class="journal-trigger" type="button" data-journal>{icon('book')}<span>MEU GRIMÓRIO</span></button><button class="icon-button menu-trigger" type="button" id="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Abrir menu">{icon('menu')}</button></div></div></header>'''
def footer(prefix=''):
 return f'''<footer class="footer"><div class="container"><div class="footer-top"><div class="footer-copy">{brand(prefix)}<p>Um universo de imaginação para cultivar o que é humano. Uma criação de Aldenir Rocha de Oliveira Filho.</p></div><div class="footer-links"><div><strong>Explore</strong><a href="{prefix}index.html#escolas">As seis escolas</a><a href="{prefix}index.html#atlas">Atlas do universo</a><a href="{prefix}index.html#galeria">Galeria visual</a></div><div><strong>Essência</strong><a href="{prefix}index.html#manifesto">Nosso manifesto</a><a href="{prefix}index.html#selo-a">Selo A</a><button type="button" data-privacy>Privacidade e escolhas</button></div></div></div><div class="footer-bottom"><p>© 2026 Reametaverso · Projeto 360X<br>Universo ficcional e cultural. Escolas de livre escolha, sem classificações morais ou diagnósticas.</p><p>Menos complexidade. Mais tempo para viver.</p></div></div></footer>'''
def dialogs():
 return f'''<dialog id="journal" class="journal-dialog" aria-labelledby="journal-title"><div class="dialog-top"><h2 id="journal-title">Meu grimório</h2><button class="icon-button" type="button" data-close="journal" aria-label="Fechar grimório">{icon('close')}</button></div><div class="dialog-body"><p class="dialog-intro">Seu caderno de caminhos. Escolha quantas escolas desejar e registre uma ideia. Não há teste, pontuação ou escola definitiva.</p><span class="field-label" id="school-label">Minhas escolas de interesse</span><div class="journal-schools" id="journal-schools" role="group" aria-labelledby="school-label"></div><label class="field-label" for="journal-note">O que desejo lembrar?</label><textarea id="journal-note" class="journal-note" maxlength="3000" placeholder="Uma ideia, um encontro, um pequeno próximo passo…" aria-describedby="journal-hint"></textarea><div class="field-hint" id="journal-hint"><span>As notas só são gravadas ao selecionar “Salvar”.</span><span id="note-counter">0 / 3000</span></div><div class="journal-buttons"><button class="button small" type="button" id="save-note">{icon('check')}Salvar nota</button><button class="button ghost small" type="button" id="export-journal">{icon('download')}Exportar texto</button><button class="button ghost small" type="button" id="ask-reset">Limpar grimório</button></div><div id="reset-confirm" class="journal-warning" hidden>Apagar as escolas escolhidas e a nota deste navegador? Esta ação não pode ser desfeita.<div><button class="button small" type="button" id="confirm-reset">Apagar</button><button class="button ghost small" type="button" id="cancel-reset">Cancelar</button></div></div><p class="privacy-text" id="storage-notice">Armazenamento apenas neste navegador, neste dispositivo. Nenhuma conta, rastreador, IA externa ou envio de suas notas ao servidor. Evite registrar senhas ou informações sensíveis. Use “Exportar texto” para manter uma cópia.</p></div></dialog>
<dialog id="lightbox" class="lightbox" aria-labelledby="lightbox-title"><button class="icon-button lightbox-close" type="button" data-close="lightbox" aria-label="Fechar imagem">{icon('close')}</button><img id="lightbox-image" class="lightbox-image" alt=""><div class="lightbox-foot"><div class="lightbox-text"><h2 id="lightbox-title">Galeria do Reametaverso</h2><p id="lightbox-description"></p></div><span class="lightbox-index" id="lightbox-index"></span><div class="lightbox-controls"><button class="icon-button" type="button" id="previous-image" aria-label="Imagem anterior">{icon('arrow-left')}</button><button class="icon-button" type="button" id="next-image" aria-label="Próxima imagem">{icon('arrow')}</button></div></div></dialog>
<dialog id="privacy" class="info-dialog" aria-labelledby="privacy-title"><div class="dialog-top"><h2 id="privacy-title">Privacidade e escolhas</h2><button class="icon-button" type="button" data-close="privacy" aria-label="Fechar privacidade">{icon('close')}</button></div><div class="dialog-body"><p>Esta versão é um site estático. O código não usa anúncios, rastreadores, fontes remotas, cookies de publicidade, login ou serviços de inteligência artificial.</p><h3>Seu grimório fica com você</h3><p>As escolas escolhidas, a nota salva e a preferência de modo foco ficam no armazenamento local do navegador. Não são transmitidas pelo site. A limpeza dos dados do navegador também pode apagar essas informações. Exporte as notas que desejar conservar.</p><h3>Hospedagem</h3><p>Ao acessar uma versão publicada, o provedor de hospedagem recebe os dados técnicos necessários à conexão e pode manter registros próprios. Este site não controla esses registros.</p><h3>Liberdade de participar</h3><p>As escolas são afinidades criativas, não diagnósticos nem avaliações de caráter. A magia pertence à narrativa ficcional. As atividades são convites opcionais; não substituem cuidados profissionais.</p></div></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div>'''
def head(title,desc,prefix='',hero='hero'):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090f15"><meta name="description" content="{html.escape(desc,quote=True)}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta name="referrer" content="strict-origin-when-cross-origin"><meta http-equiv="Content-Security-Policy" content="default-src 'self' file:; img-src 'self' file: data:; style-src 'self' 'unsafe-inline' file:; script-src 'self' file:; font-src 'self' file:; connect-src 'none'; object-src 'none'; base-uri 'self'; form-action 'none'"><title>{title}</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preload" as="image" href="{prefix}assets/images/{hero}.webp"><link rel="stylesheet" href="{prefix}assets/styles.css"><script src="{prefix}assets/data.js" defer></script><script src="{prefix}assets/app.js" defer></script></head>'''
def card(s):
 return f'''<a class="school-card" href="escolas/{s['id']}.html" style="--school-color:{s['color']}"><div class="card-photo"><img src="assets/images/{s['id']}-card.webp" width="720" height="405" alt="Arquitetura da {s['title']} no universo ficcional Reametaverso" loading="lazy" decoding="async"><span class="card-number">{s['number']} / 06</span></div><div class="card-info"><span class="school-symbol">{icon(s['icon'])}</span><span class="card-kicker">Escola da{' ' if s['id']!='cuidado' else ' '}<span class="sr-only">{s['name']}</span></span><h3>{s['name']}</h3><p>{s['description']}</p><div class="card-footer"><span>{' · '.join(s['tags'])}</span>{icon('arrow')}</div></div></a>'''.replace('Escola da <span class="sr-only">Cuidado','Escola do <span class="sr-only">Cuidado')
# O conteúdo principal é acessível sem JavaScript.
s=data['schools'][0]
points=[('sabedoria','I',19,36),('criacao','II',49,35),('tecnologia','III',82,35),('natureza','IV',17,63),('cuidado','V',49,77),('coragem','VI',83,65)]
atlas_buttons=''.join(f'<button type="button" class="map-point" data-atlas="{key}" style="left:calc({x}% - 18px);top:calc({y}% - 18px)" aria-label="Conhecer a {next(z["title"] for z in data["schools"] if z["id"]==key)}" aria-pressed="{str(key=="sabedoria").lower()}">{num}</button>' for key,num,x,y in points)
map_tabs=''.join(f'<button type="button" data-atlas="{s["id"]}" aria-pressed="{str(s["id"]=="sabedoria").lower()}">{s["name"]}</button>' for s in data['schools'])
gallery=''.join(f'<button class="gallery-item" type="button" data-gallery="{g["id"]}" data-category="{g["school"]}" aria-label="Ampliar: {g["title"]}"><img src="assets/images/{g["id"]}.webp" alt="{g["title"]} — ilustração ficcional" width="1672" height="941" loading="lazy" decoding="async"><span class="gallery-caption"><span><strong>{g["title"]}</strong><small>{g["subtitle"]}</small></span>{icon("expand")}</span></button>' for g in data['gallery'])
filters='<button class="filter" data-filter="todas" aria-pressed="true" type="button">Todas as imagens</button>'+''.join(f'<button class="filter" data-filter="{s["id"]}" aria-pressed="false" type="button">{s["name"]}</button>' for s in data['schools'])
home=head('Reametaverso — Magia para imaginar. Tempo para viver.','Explore as seis escolas do Reametaverso: um universo de magia, cultura, natureza e tecnologia a serviço da vida.')+f'''<body data-base="" data-page="home">{header()}
<main id="conteudo"><section class="hero" id="universo" aria-labelledby="hero-title"><img class="hero-art" src="assets/images/hero.webp" width="1672" height="782" alt="Universidade ficcional gótica contemporânea com seis escolas, lagos e jardins iluminados" fetchpriority="high"><div class="container"><div class="hero-copy"><div class="eyebrow">Um universo de livre escolha</div><h1 id="hero-title">Magia para imaginar.<br><em>Tempo para viver.</em></h1><p>Entre o extraordinário e o essencial, existe um lugar para o seu jeito de ser. Descubra as escolas do Reametaverso.</p><div class="hero-actions"><a class="button" href="#escolas">Explore as escolas {icon('arrow')}</a><a class="button ghost" href="#atlas">{icon('compass')}Abra o atlas</a></div></div></div><div class="hero-badge">{icon('spark')}<p>O tempo<br>pertence a você.</p><span>Tempo das Essências</span></div><div class="hero-foot container"><a class="scroll" href="#escolas">SIGA SUA CURIOSIDADE</a><span>UM MUNDO FICCIONAL.<br>INSPIRAÇÕES PARA A VIDA REAL.</span></div></section>
<div class="container"><div class="intro-strip"><div>{icon('compass')}<span><strong>Seis escolas</strong><small>Infinitas combinações</small></span></div><div>{icon('heart')}<span><strong>Uma essência</strong><small>O respeito por cada pessoa</small></span></div><div>{icon('spark')}<span><strong>Livre escolha</strong><small>Seu caminho pode mudar</small></span></div></div></div>
<section class="section" id="escolas" aria-labelledby="schools-heading"><div class="container"><div class="section-head"><div><div class="eyebrow">Encontre o que desperta você</div><h2 id="schools-heading">Seis escolas.<br>Um mundo de possibilidades.</h2></div><p>Não há uma escola certa para cada pessoa.<br>Há caminhos que você pode explorar, combinar e reinventar.</p></div><div class="school-grid">{''.join(card(s) for s in data['schools'])}</div><p class="section-note">Afinidades, não rótulos. Você pode fazer parte de várias escolas — ou apenas visitar.</p></div></section>
<section class="section atlas-section" id="atlas" aria-labelledby="atlas-heading"><div class="container"><div class="section-head"><div><div class="eyebrow">Um atlas de possibilidades</div><h2 id="atlas-heading">Todo caminho tem uma história.</h2></div><p>As escolas se conectam por pontes, jardins e encontros. Selecione uma escola para conhecer seu território.</p></div><div class="atlas-shell"><div class="atlas-map"><img src="assets/images/mapa.webp" width="1672" height="941" loading="lazy" alt="Atlas das seis escolas em torno da árvore do Tempo das Essências">{atlas_buttons}<span class="map-tip">SELECIONE UM DOS SEIS PORTAIS</span></div><div class="atlas-panel" id="atlas-panel" aria-live="polite"><span class="school-symbol" id="atlas-symbol">{icon('book')}</span><small id="atlas-number">TERRITÓRIO 01 / 06</small><h3 id="atlas-title">Sabedoria</h3><p id="atlas-description">{data['schools'][0]['description']}</p><div class="tags" id="atlas-tags">{''.join(f'<span class="tag">{t}</span>' for t in data['schools'][0]['tags'])}</div><a class="button ghost small" id="atlas-link" href="escolas/sabedoria.html">Entre na escola {icon('arrow')}</a></div></div><div class="map-tabs" role="group" aria-label="Selecionar escola no atlas">{map_tabs}</div></div></section>
<section class="section" id="essencias" aria-labelledby="essence-heading"><div class="container essence-grid"><figure class="essence-photo"><img src="assets/images/essencias.webp" width="1672" height="941" loading="lazy" alt="Árvore luminosa rodeada por caminhos e pessoas no Tempo das Essências"><figcaption>O CENTRO DO UNIVERSO. O INÍCIO DE UM ENCONTRO.</figcaption></figure><div class="essence-copy"><div class="eyebrow">Tempo das Essências</div><h2 id="essence-heading">Onde os caminhos<br><em>se encontram.</em></h2><p>Uma praça, uma árvore, uma conversa. No coração do Reametaverso, o extraordinário abre espaço para as coisas simples.</p><blockquote>“A tecnologia deve devolver tempo para viver.”</blockquote><p>Você pode explorar por curiosidade, seguir uma pequena missão ou simplesmente fazer uma pausa. Nenhum modo define quem você é.</p><div class="journeys" role="group" aria-label="Escolha uma experiência"><button type="button" class="journey" data-journey="explorar">{icon('compass')}<strong>Explorar</strong><small>Siga a curiosidade</small></button><button type="button" class="journey" data-journey="missao">{icon('spark')}<strong>Criar</strong><small>Um pequeno passo</small></button><button type="button" class="journey" data-journey="pausa">{icon('moon')}<strong>Pausar</strong><small>Sem metas agora</small></button></div><div class="mission-box" id="mission-box" hidden aria-live="polite"><div class="eyebrow" id="mission-kicker"></div><h3 id="mission-title"></h3><p id="mission-text"></p><button type="button" class="text-link" id="mission-save">Guardar no grimório {icon('arrow')}</button></div></div></div></section>
<section class="section gallery-section" id="galeria" aria-labelledby="gallery-heading"><div class="container"><div class="section-head"><div><div class="eyebrow">Coleção visual · Turbo TEMI 360X</div><h2 id="gallery-heading">Janelas para o Reametaverso.</h2></div><p>Dez cenas, entre arquitetura gótica, luz e natureza. Abra uma imagem para contemplar os detalhes.</p></div><div class="filter-bar" role="group" aria-label="Filtrar galeria por escola">{filters}</div><div class="gallery-grid" id="gallery-grid">{gallery}</div><p class="gallery-count" id="gallery-count" role="status">10 imagens · Clique para ampliar · Use as setas do teclado na galeria.</p></div></section>
<section class="section" id="manifesto" aria-labelledby="manifesto-heading"><div class="container"><div class="manifesto-intro"><div class="eyebrow">O que escolhemos preservar</div><h2 id="manifesto-heading">O futuro pode ser extraordinário.<br>E a vida, mais simples.</h2><p>Livros que se abrem. Conversas que se demoram. Jogos que aproximam. Tecnologia que ajuda, sem ocupar todos os espaços. O Reametaverso nasce para imaginar esse equilíbrio — com liberdade, dignidade e respeito.</p></div><div class="principles"><article class="principle">{icon('book')}<h3>Preservar o essencial.</h3><p>Valorizar leitura, memória, cultura e encontros humanos. Conservar alternativas sem impor um único jeito de viver.</p></article><article class="principle">{icon('orbit')}<h3>Simplificar o complexo.</h3><p>Usar a tecnologia como ferramenta. Compreender, escolher e manter a possibilidade de recusar, corrigir ou mudar de direção.</p></article><article class="principle">{icon('leaf')}<h3>Cuidar do que permanece.</h3><p>Respeitar pessoas, recursos e natureza. Fazer do cuidado uma prática concreta, não apenas uma promessa.</p></article></div><div class="seal" id="selo-a"><span class="seal-mark" aria-hidden="true">A</span><div class="seal-copy"><h3>Selo A</h3><p>Autenticação Patrimonial Humanitária. Uma proposta de reconhecimento para serviços que simplifiquem a vida, preservem experiências humanas e cuidem da natureza.</p><small>PROPOSTA CONCEITUAL · SEM CERTIFICAÇÕES EMITIDAS</small><details><summary>Conheça os critérios propostos</summary><ul><li>Tempo e simplicidade — 20 pontos.</li><li>Liberdade de canal — 15 pontos.</li><li>Contato humano — 15 pontos.</li><li>Patrimônio, cultura e convivência — 10 pontos.</li><li>Acessibilidade e compreensão — 15 pontos.</li><li>Natureza e uso de recursos — 15 pontos.</li><li>Autonomia e respeito à pessoa — 10 pontos.</li></ul><p class="details-note">Matriz autoral experimental. O corte proposto é 80/100, pelo menos metade em cada eixo e todos os requisitos obrigatórios. A avaliação recai sobre serviços, nunca sobre a dignidade das pessoas. Doações não compram aprovação. O programa ainda depende de piloto e revisão.</p></details></div></div></div></section>
<section class="invitation" aria-labelledby="invitation-heading"><div class="container"><div class="eyebrow">O próximo capítulo é seu</div><h2 id="invitation-heading">Não é preciso escolher<br>um único caminho.</h2><p>Guarde as escolas que despertam seu interesse. Volte quando fizer sentido. Seu grimório fica apenas com você.</p><button class="button" type="button" data-journal>{icon('book')}Abrir meu grimório</button></div></section></main>{footer()}{dialogs()}<noscript><p class="container">As páginas das escolas e os textos funcionam sem JavaScript. Ative-o para utilizar o atlas interativo, a ampliação das imagens e o grimório local.</p></noscript></body></html>'''
(ROOT/'index.html').write_text(home,encoding='utf-8')
for s in data['schools']:
 p='../'
 practice=''.join(f'<article class="practice-card"><small>CONVITE 0{i+1} · {x["time"]}</small><h3>{x["title"]}</h3><p>{x["text"]}</p><button class="text-link" type="button" data-save-practice="{i}" data-school-id="{s["id"]}">Guardar este convite {icon("arrow")}</button></article>' for i,x in enumerate(s['practices']))
 other=''.join(f'<a href="{x["id"]}.html">{icon(x["icon"])}{x["name"]}</a>' for x in data['schools'] if x['id']!=s['id'])
 page=head(f'{s["title"]} — Reametaverso',s['description'],p,s['id']+'-scene')+f'''<body data-base="../" data-page="{s['id']}" style="--school-color:{s['color']}">{header(p)}<main id="conteudo"><section class="hero school-hero"><img class="hero-art" src="../assets/images/{s['id']}-scene.webp" width="1440" height="617" alt="Paisagem da {s['title']}" fetchpriority="high"><div class="container"><div class="hero-copy"><nav class="breadcrumb" aria-label="Caminho de navegação"><a href="../index.html">Reametaverso</a><span aria-hidden="true">/</span><a href="../index.html#escolas">As escolas</a><span aria-hidden="true">/</span><span aria-current="page">{s['name']}</span></nav><div class="eyebrow">TERRITÓRIO {s['number']} / 06 · ESCOLA DE LIVRE ESCOLHA</div><h1>{s['name']}</h1><p>{s['motto']}</p><div class="hero-actions"><button class="button" type="button" data-follow="{s['id']}" aria-pressed="false">{icon(s['icon'])}<span>Guardar no grimório</span></button><a class="button ghost" href="#praticas">Encontre um convite {icon('arrow')}</a></div></div></div></section><section class="section"><div class="container school-intro"><div><div class="eyebrow">A essência desta escola</div><h2>{s['place']}</h2><p>{s['intro']}</p><p>{s['placeDescription']}</p></div><div><ul class="values">{''.join(f'<li>{icon("check")}{v}</li>' for v in s['values'])}</ul><p class="section-note">Escola ficcional. Suas afinidades podem mudar e coexistir com outras escolas.</p></div></div></section><section class="section atlas-section" id="praticas"><div class="container"><div class="section-head"><div><div class="eyebrow">Do imaginário ao cotidiano</div><h2>Pequenos convites.<br>Sem obrigação de cumprir.</h2></div><p>Escolha o que combina com seu momento. Os tempos são sugestões, não metas ou testes.</p></div><div class="practice-grid">{practice}</div><figure class="school-scene"><button type="button" class="gallery-item" data-gallery="{s['related']}" aria-label="Ampliar imagem da {s['title']}"><img src="../assets/images/{s['related']}.webp" width="1672" height="941" loading="lazy" alt="Ilustração da {s['title']} no Reametaverso"></button><figcaption>{s['quote']} · Arte ficcional da coleção Turbo TEMI 360X.</figcaption></figure></div></section><section class="section"><div class="container"><div class="eyebrow">Continue a descoberta</div><div class="section-head"><h2>Outros caminhos também são seus.</h2><a class="text-link" href="../index.html#atlas">Voltar ao atlas {icon('arrow')}</a></div><div class="other-schools">{other}</div></div></section></main>{footer(p)}{dialogs()}</body></html>'''
 (ROOT/'escolas'/f'{s["id"]}.html').write_text(page,encoding='utf-8')
